  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': 'Conectar una pantalla',
  'simple.help.g1.s1': 'En la TV, tableta u computadora que quieras usar, abre el reproductor: instala la app de Android o abre la página /player de este sitio en su navegador.',
  'simple.help.g1.s2': '¿No tienes una TV a mano? Abre el reproductor en otra pestaña del navegador para probarlo.',
  'simple.help.g1.s3': 'El reproductor muestra un código de 6 dígitos. Aquí, elige «Agregar una pantalla» y escríbelo.',
  'simple.help.g1.s4': 'Ponle a la pantalla un nombre que reconozcas, como «Escaparate».',
  'simple.help.g2.title': 'Cambiar lo que muestra una pantalla',
  'simple.help.g2.s1': 'Elige «Cambiar lo que muestra una pantalla» o toca la pantalla en «Tus pantallas».',
  'simple.help.g2.s2': 'Elige «Reemplazar» para mostrar solo lo nuevo, o «Agregar» para mantener lo que ya se reproduce.',
  'simple.help.g2.s3': 'Sube fotos o videos, elige algunos que ya subiste o muestra lo mismo que otra pantalla.',
  'simple.help.g2.s4': 'La pantalla se actualiza en pocos segundos.',
  'simple.help.g3.title': 'Subir fotos y videos',
  'simple.help.g3.s1': 'Elige «Subir fotos» y selecciona todos los archivos que quieras, o arrástralos.',
  'simple.help.g3.s2': 'Marca las pantallas que deben mostrarlos, o desmárcalas todas para guardarlos para más tarde.',
  'simple.help.g3.s3': 'Las fotos se muestran 10 segundos cada una; los videos se reproducen hasta el final.',
  'simple.help.q1': '¿Qué puedo usar como pantalla?',
  'simple.help.a1': 'Televisores Android, TV boxes y tabletas, Fire TV, televisores inteligentes LG y Samsung, Raspberry Pi, Windows y ChromeOS, o cualquier dispositivo con navegador web.',
  'simple.help.q2': 'Mi pantalla no cambia. ¿Qué debo comprobar?',
  'simple.help.a2': 'Comprueba que la pantalla indica «Reproduciendo» en la página de inicio. Si dice «Desconectada», comprueba que el dispositivo está encendido y conectado a internet; recibirá tus cambios en cuanto se vuelva a conectar.',
  'simple.help.q3': '¿Qué pasa si se cae internet?',
  'simple.help.a3': 'Las pantallas guardan el contenido localmente y siguen reproduciéndolo. Los cambios nuevos llegan cuando vuelve la conexión.',
  'simple.help.q4': '¿Qué archivos puedo subir?',
  'simple.help.a4': 'Fotos (JPEG, PNG, GIF, WebP) y videos (MP4 funciona mejor), además de audio. Los PDF se pueden subir desde la página de contenido en la vista «Avanzada».',
  'simple.help.q5': '¿Cómo cambio el nombre de una pantalla o la quito?',
  'simple.help.a5': 'Cambia a «Avanzada» (arriba a la derecha), abre «Pantallas», haz clic en la pantalla y usa Cambiar nombre o Quitar en la parte superior de su página.',
  'simple.help.q6': '¿Puedo mostrar cosas distintas a distintas horas del día?',
  'simple.help.a6': 'Sí: eso es «Horario», en la vista «Avanzada». La vista sencilla siempre muestra el mismo contenido en una pantalla hasta que lo cambies.',
  'simple.help.trial_q': '¿Cómo funciona la prueba gratuita?',
  'simple.help.trial_a': 'Tienes 14 días del plan Pro con todas las funciones y sin tarjeta. Al terminar pasas al plan Free: no se borra nada, y las pantallas que superen el límite del plan Free se pausan hasta que elijas un plan.',
  'stats.prompt.title': '¿Nos ayudas a saber cuánto se usa ScreenTinker?',
  'stats.prompt.body': 'Como la mayoría de las instalaciones son privadas, no sabemos cuántas pantallas hay. Al compartir se envía un ID aleatorio, la versión y cuántas pantallas usas; nada más, nunca. Puedes cambiarlo en cualquier momento en Configuración.',
  'stats.prompt.share': 'Compartir',
  'stats.prompt.no': 'No, gracias',
  'stats.prompt.thanks': 'Gracias: se comparten las estadísticas de instalación',
  // 3.0: Simple view, workspaces and view-only members
  'simple.menu.workspace': 'Espacio de trabajo',
  'simple.menu.more_workspaces': '{n} más en la vista avanzada',
  'simple.home.in_workspace': 'En {name}',
  'simple.home.title_viewer': 'Tus pantallas de un vistazo',
