  'migrate.field.region': 'Región',
  'migrate.how.xibo': 'En Xibo, abre Administration, luego Applications, y agrega una Application con «Client Credentials» marcado. Copia su Client ID y su Client Secret. Escribe la dirección de tu CMS (donde inicias sesión), por ejemplo https://cms.example.com.',
  'migrate.how.yodeck': 'En Yodeck, abre Account Settings, Advanced Settings, API Tokens, y genera un token (plan Premium o Enterprise). Pégalo como etiqueta:token. Yodeck no entrega por su API las imágenes y documentos originales que subiste: aparecen en una lista para que los agregues con la importación por zip. Los videos llegan en la versión que reproduce Yodeck.',
  'migrate.how.optisigns': 'OptiSigns tiene una API, pero no documenta ninguna forma de descargar tus archivos, así que una lista de reproducción llegaría vacía. Descarga tus archivos desde OptiSigns y usa la importación por zip: una carpeta por lista de reproducción, o un playlists.csv.',
  'migrate.how.screencloud': 'En ScreenCloud Studio, abre Account Settings, luego la pestaña Developer, y crea un token con permisos de lectura. Elige la región que aparece ahí (EU o US). ScreenCloud guarda reglas de horario en elementos individuales de los canales; esas se listan, pero no se importan.',
  'migrate.how.anthias': 'Escribe la dirección de tu dispositivo Anthias, por ejemplo http://192.168.1.20. Si activaste la autenticación, escribe su nombre de usuario y contraseña. Cada dispositivo se importa como una pantalla con una lista de reproducción.',
  'migrate.how.screenly': 'En Screenly, abre Settings, Security, Tokens y agrega un token. Se traen las listas de reproducción, etiquetas y pantallas; las reglas simples de día y hora se convierten en horarios.',
  'migrate.how.generic_zip': 'Sube un zip con tus medios. Cada carpeta se convierte en una lista de reproducción. Si quieres, agrega playlists.csv (columnas: playlist, file, duration, order) y screens.csv (columnas: name, group, playlist).',
  'migrate.scanning': 'Leyendo lo que hay. Las cuentas grandes tardan unos minutos.',
