  'platform.rollouts.desc': 'Un nuevo reproductor Android, Pi o Windows llega al 10% de las pantallas de esa plataforma, después al 50% y finalmente a todas. Cada fase espera a que las pantallas actualizadas funcionen correctamente. Si fallan o dejan de mostrar contenido más que las demás, el despliegue se detiene automáticamente y recibes un correo. Las pantallas Pi y Windows que recibieron una versión detenida vuelven a la anterior. Android no puede volver a una versión antigua: detener el despliegue frena su expansión y la solución es una compilación más nueva. Las pantallas del canal beta y Forzar actualización omiten las fases.',
