  'audience.title': 'Audiencia',
  'audience.subtitle': 'Cuántas personas miraron tus pantallas y durante cuánto tiempo. Desactivado hasta que lo actives.',
  'audience.privacy_heading': 'Cómo funciona y qué no hace nunca',
  'audience.privacy_1': 'La cámara de la pantalla y un detector integrado en el reproductor detectan las caras que miran hacia ella. Todo se procesa en la propia pantalla.',
  'audience.privacy_2': 'No se guarda ni sale de la pantalla ninguna imagen, vídeo, cara ni información que pueda identificar a una persona. Cada fotograma se descarta en cuanto se termina el recuento.',
  'audience.privacy_3': 'Solo se envían cifras: por minuto, cuántas personas eran visibles, cuántas miraron y durante cuánto tiempo. No se reconoce a nadie, no se sigue a las personas entre minutos ni se les asigna edad o género.',
  'audience.privacy_4': 'El servidor rechaza cualquier dato que no sea una de esas cifras, así que el reproductor no podría enviar más información aunque lo intentara.',
  'audience.privacy_notice_hint': 'Informa a las personas de dónde haces recuentos. docs/audience-counting.md incluye un aviso listo para imprimir. Revisa la normativa aplicable donde estén tus pantallas (RGPD, BIPA, CCPA y otras) antes de activarlo.',
