  'widget.web.interactive_hint': 'Los visitantes pueden tocar, desplazarse y rellenar formularios. La lista se pausa mientras alguien usa la página; al irse, la página se restablece y se borra todo lo que haya hecho. Solo a pantalla completa. Compatibilidad completa en Android, reproductores nativos de Windows y Raspberry Pi, y BrightSign; las pantallas web, webOS y Tizen tienen una versión limitada que no puede borrar los datos del sitio ni bloquear otros sitios.',
