  'widget.web.idle_warning_sec': '{n} segundos',
  'widget.web.idle_warning_hint': 'Da al visitante un momento para tocar y continuar. Es útil en una tienda; en una página informativa puede desactivarse.',
  'widget.web.wipe_site_data': 'Borrar las cookies y el almacenamiento del sitio después de cada visitante',
  'widget.web.wipe_site_data_hint': 'Desactívalo en páginas informativas sin nada que proteger (menús, precios, mapas): así se conservan el consentimiento de cookies y el idioma elegido. Cada visitante sigue recibiendo una página, historial y formularios nuevos. Todas las páginas web de una pantalla comparten almacenamiento, por lo que la limpieza de otro elemento también lo borra. Los reproductores de Windows y Raspberry Pi conservan las cookies, pero no el almacenamiento del sitio; BrightSign siempre lo borra todo.',
  'widget.web.keep_consent': 'Conservar la elección de consentimiento de cookies entre visitantes',
  'widget.web.keep_consent_hint': 'Solo se conservan las cookies de consentimiento de los sitios permitidos. Los inicios de sesión, carritos y demás datos se borran tras cada visitante. Las herramientas que guardan la elección en localStorage en vez de una cookie seguirán preguntando.',
  'widget.web.keep_cookie_names': 'Otros nombres de cookies que se conservarán',
  'widget.web.keep_cookie_names_ph': 'p. ej., shop_consent, cc_*',
  'widget.web.keep_cookie_names_hint': 'Las herramientas habituales de consentimiento (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi y otras) ya se reconocen. Un * al final coincide con un prefijo. Nunca añadas aquí cookies de inicio de sesión o de carrito.',
  'widget.web.zoom_hint': 'El porcentaje de zoom de arriba también se aplica a la página interactiva: 150 hace que un sitio de escritorio se distribuya como si la pantalla tuviera dos tercios de su tamaño.',
